import json

# Check ICG experiments for SC baseline
for exp_name in ['exp074_icg_mistral_folio', 'exp074c_icg_mistral_folio_seed123', 'exp074d_icg_mistral_folio_seed456']:
    path = f'/root/symb_invariant_consensus/results/{exp_name}/results.json'
    try:
        d = json.load(open(path))
        # Look for SC baseline
        sc_keys = [k for k in d.keys() if 'sc' in k.lower() or 'baseline' in k.lower() or 'summary' in k.lower()]
        if 'baselines' in d:
            print(f"{exp_name}: baselines = {d['baselines']}")
        elif 'summary' in d:
            s = d['summary']
            print(f"{exp_name}: sc_accuracy = {s.get('sc_accuracy')}, sica_accuracy = {s.get('sica_accuracy')}")
        else:
            # Check top-level
            for k in d:
                if isinstance(d[k], dict) and 'accuracy' in str(d[k]):
                    print(f"{exp_name}.{k} = {d[k]}")
                    break
            else:
                print(f"{exp_name}: keys = {list(d.keys())[:10]}")
    except Exception as e:
        print(f"{exp_name}: {e}")

# Also check exp067 seed789
d = json.load(open('/root/symb_invariant_consensus/results/exp067_mistral_folio_seed789/exp067_results.json'))
s = d['summary']
print(f"\nexp067_seed789: sc_accuracy = {s.get('sc_accuracy')}, sica_accuracy = {s.get('sica_accuracy')}")

# Check exp075b contrastive for seeds
for exp_name in ['exp075b_contrastive_mistral_folio']:
    path = f'/root/symb_invariant_consensus/results/{exp_name}/results.json'
    try:
        d = json.load(open(path))
        if 'baselines' in d:
            print(f"\n{exp_name}: baselines = {d['baselines']}")
    except:
        pass
PYEOF
